-- mod-tome/data/talents/gifts/cold-drake.lua
-- Total: 8 cadenas
-- Estado: ⏳ Pendiente
-- Ultima actualizacion: --
-- Traductor: --

t("Ice Claw", "Hielo Claw", "talent name")
t("Icy Skin", "Icy Piel", "talent name")
t("Ice Wall", "Hielo Wall", "talent name")
t("ice wall", "muro de hielo", "_t")
t("a summoned, transparent wall of ice", "una pared de hielo convocada y transparente", "_t")
t("Ice Breath", "Aliento de hielo", "talent name")
t("@Source@ breathes ice!", "@Source@ respira hielo!", "_t")
t("%s resists the freeze!", "%s resiste la congelación!", "logSeen")

t("You call upon the mighty claw of a cold drake and rake a wave of freezing cold in front of you, doing %d%% weapon damage as Ice damage in a cone of radius %d. Ice damage gives a chance of freezing the target.\n\t\tEvery level in Ice Claw additionally raises your Physical Save by 2.\n\t\tEach point in cold drake talents also increases your cold resistance by 1%%.\n\n\t\tThis talent will also attack with your shield, if you have one equipped.", "Llamas a la poderosa garra de un drake frío y rasgas una ola de frío helado delante de ti, haciendo daño de arma %d %% como daño de hielo en un cono de %d radio. El daño en el hielo da la oportunidad de congelar el objetivo.\nCada nivel de garra de hielo aumenta su ahorro físico por 2.\nCada punto en los talentos del drake frío también aumenta su resistencia fría por 1%%.\n\nEste talento también atacará con su escudo, si tiene uno equipado.", "tformat")
t("Your skin forms icy scales and your flesh toughens, increasing your Maximum Life by %d%% and your Armour by %d.\n\t\tYou also deal %0.2f cold damage to any enemies that physically strike you.\n\t\tEach point in cold drake talents also increases your cold resistance by 1%%.\n\t\tThe life increase will scale with your Talent Level, and your Armour and retaliation cold damage will scale with Mindpower.", "Tu piel forma escalas heladas y tu carne se endurece, aumentando tu vida máxima por %d %% y tu armadura por %d.\nTambién se hace daño a cualquier enemigo que te golpee físicamente.\nCada punto en los talentos del drake frío también aumenta su resistencia fría por 1%%.\nEl aumento de la vida se escalará con su nivel de talento, y su armadura y represalia daño frío escalará con la fuerza mental.", "tformat")
t("Summons an icy wall of %d length for %d turns. Ice walls are transparent, but block projectiles and enemies.\n\t\tIce walls also emit freezing cold, dealing %0.2f damage for each ice wall within radius %d of an enemy, and with each wall giving a 25%% chance to freeze an enemy. This cold cannot hurt the talent user or their allies.\n\t\tEach point in cold drake talents also increases your cold resistance by 1%%.", "Invoca una pared helada de longitud de %d para giros %d. Las paredes de hielo son transparentes, pero bloquean proyectiles y enemigos.\nLas paredes de hielo también emiten frío congelante, causando daños de %0.2f por cada pared de hielo dentro de %d radio de un enemigo, y con cada pared dando una oportunidad de 25%% para congelar a un enemigo. Este frío no puede dañar al usuario talentoso o a sus aliados.\nCada punto en los talentos fríos de drake también aumenta su resistencia fría por 1%%.", "tformat")
t("You breathe ice in a frontal cone of radius %d. Any target caught in the area will take %0.2f cold damage and be frozen for 3 turns.\n\t\tThe damage will increase with your Strength, the critical chance is based on your Mental crit rate, and the Freeze apply power is based on your Mindpower.\n\t\tEach point in cold drake talents also increases your cold resistance by 1%%.", "Respira hielo en un cono frontal de %d radio. Cualquier objetivo atrapado en la zona tendrá un daño frío de %0.2f y se congelará durante 3 vueltas.\nEl daño aumentará con su fuerza, la oportunidad crítica se basa en su tasa de criminalidad mental, y el poder de aplicación Freeze se basa en su poder mental.\nCada punto en los talentos fríos de drake también aumenta su resistencia fría por 1%%.", "tformat")
